promql:
sum by (instance)(
  node_network_tcp_connections{state="tw"}
  * on(instance) group_left(service) (
    node_network_tcp_connections{state="tw"}
    * on(instance) group_right(service) (
      service{service="ts-travel-service"}
      * on(pod) group_left(node) (
        pod{namespace="default"} == "ts-travel-service-c598b7879-6mllj"
        or
        pod{namespace="default"} == "ts-travel-service-c598b7879-bb7s2"
      )
      * on(node) group_right(instance) (
        node{node=~"k8s-node1|k8s-node4"}
      )
    )
  )
)
